    tuto_paso:"STEP {i} / {n}",
    tuto_fin:"Let's play!",
    tuto_sig:"Next ›",
    tuto_ca_1_t:"Your career",
    tuto_ca_1_x:"You're <b>16 years old</b>, with 2,500€ and the real 52-week calendar. The week runs <b>Monday to Sunday</b>: you enter (or not) on Monday, and each day you choose to train or rest. If there's a tournament, qualifying falls on Tuesday-Wednesday, the last 16 on Thursday... and the final, on Sunday.",
    tuto_ca_2_t:"Two circuits",
    tuto_ca_2_x:"Every week there's an open <b>Continental</b> tournament and, most weeks, an <b>Elite</b> with a ranking cut. If you miss an Elite's cut, you can burn one of your <b>2 yearly wildcards</b> to sneak into its qualifying.",
    tuto_ca_3_t:"Tournaments",
    tuto_ca_3_x:"Each round is played <b>on its day</b>. In matches you watch, you're in charge: <b>live tactics</b> (aggression, targeting the weak one), a <b>timeout</b> between sets with your talk, and <b>3 video reviews</b>. After big matches, the press will want headlines — watch your words.",
    tuto_ca_4_t:"Your partner",
    tuto_ca_4_x:"Your partner has <b>chemistry</b> (grows by playing together) and <b>morale</b>: lose early and often and they burn out — and may leave you at the end of the season. In the market you can sign free agents or poach players from the circuit.",
    tuto_ca_5_t:"The money",
    tuto_ca_5_x:"Real prize money (a Crown pays 60,000€ to the champion pair; a Continental Bronze, 800€), travel that costs (Dubai isn't Valladolid), sponsorships with goals and your team: a salaried specialist coach, physio, psychologist, trainer and an <b>agent</b> who takes 15%.",
    tuto_ca_6_t:"The world lives",
    tuto_ca_6_x:"At season's end the ranking carries over 55%, veterans retire, youngsters debut and pairs break up. The goal: reach an Elite main draw... and one day, the no. 1. Good luck!",
    tuto_cl_1_t:"Your club",
    tuto_cl_1_x:"You manage a <b>men's or women's</b> club (you choose when founding it): you sign players from that circuit and compete in its ranking. The squad (up to 6) earns a weekly wage; members and prize money keep the coffers going.",
    tuto_cl_2_t:"Two pairs",
    tuto_cl_2_x:"In Squad you assign <b>pair A</b> and <b>pair B</b>. Pair A plays its tournament with you on the bench; pair B can go to another tournament in parallel (quick result, scores 50% for the club).",
    tuto_cl_3_t:"The calendar",
    tuto_cl_3_x:"Open Continental every week; Elite (Elite 2/Elite 1/Crown) with a cut by club ranking. Energy and injuries decide who you can field.",
    tuto_cl_4_t:"Training",
    tuto_cl_4_x:"Each player has a <b>plan</b> (a specific shot or auto). One button trains the whole squad at once. Facilities, gym and video room improve performance.",
    tuto_cl_5_t:"Money and signings",
    tuto_cl_5_x:"Free-agent market (the scout brings gems), an academy with prospects, club renovations, coaching staff... and <b>rival clubs</b> that sign players and will come with offers for yours: you decide whether to sell.",
    tuto_cl_6_t:"The goal",
    tuto_cl_6_x:"The <b>board</b> sets a ranking goal every season: meet it and extra budget arrives; fail two years in a row and <b>you're sacked</b>. Watch the market: other players' levels are ranges — the scout sharpens reports and sniffs out each prospect's ceiling.",
