    tuto_fin:"À nous de jouer !",
    tuto_sig:"Suivant ›",
    tuto_ca_1_t:"Ta carrière",
    tuto_ca_1_x:"Tu as <b>16 ans</b>, 2 500€ et le vrai calendrier de 52 semaines. La semaine va <b>du lundi au dimanche</b> : le lundi tu t'inscris (ou pas), et chaque jour tu choisis entre t'entraîner ou te reposer. S'il y a un tournoi, les qualifs tombent mardi-mercredi, les huitièmes le jeudi... et la finale, le dimanche.",
    tuto_ca_2_t:"Deux circuits",
    tuto_ca_2_x:"Chaque semaine il y a un tournoi <b>Continental</b> ouvert et, souvent, un <b>Élite</b> avec un cut au classement. Si tu rates le cut d'un Élite, tu peux utiliser une de tes <b>2 wildcards</b> annuelles pour te glisser dans ses qualifs.",
    tuto_ca_3_t:"Les tournois",
    tuto_ca_3_x:"Chaque tour se joue <b>le jour dit</b>. Dans les matchs que tu regardes, c'est toi qui commandes : <b>tactique en direct</b> (agressivité, viser le faible), <b>temps mort</b> entre les sets avec ta causerie, et <b>3 challenges vidéo</b>. Après les grands matchs, la presse voudra des titres — pèse tes mots.",
    tuto_ca_4_t:"Ton partenaire",
    tuto_ca_4_x:"Ton partenaire a de l'<b>alchimie</b> (elle monte en jouant ensemble) et du <b>moral</b> : si vous perdez tôt et souvent, il s'use — et peut te quitter en fin de saison. Au marché tu peux signer des agents libres ou débaucher des joueurs du circuit.",
    tuto_ca_5_t:"L'argent",
    tuto_ca_5_x:"Des prix réels (une Couronne paie 60 000€ à la paire championne ; un Continental Bronze, 800€), des voyages qui coûtent (Dubaï n'est pas Valladolid), des sponsors avec objectifs et ton équipe : entraîneur spécialiste salarié, kiné, psy, préparateur et un <b>agent</b> qui prend 15 %.",
    tuto_ca_6_t:"Le monde vit",
    tuto_ca_6_x:"À la fin de la saison le classement conserve 55 %, les vétérans se retirent, des jeunes débutent et des paires se séparent. Objectif : atteindre le tableau d'un Élite... et un jour, le n°1. Bonne chance !",
    tuto_cl_1_t:"Ton club",
    tuto_cl_1_x:"Tu es le manager d'un club <b>masculin ou féminin</b> (tu le choisis à la fondation) : tu recrutes des joueurs de ce circuit et tu joues son classement. L'effectif (jusqu'à 6) touche un salaire hebdomadaire ; adhérents et prix soutiennent la caisse.",
    tuto_cl_2_t:"Deux paires",
    tuto_cl_2_x:"Dans Effectif tu désignes la <b>paire A</b> et la <b>paire B</b>. La A joue son tournoi avec toi sur le banc ; la B peut aller à un autre tournoi en parallèle (résultat rapide, compte à 50 % pour le club).",
    tuto_cl_3_t:"Le calendrier",
    tuto_cl_3_x:"Continental ouvert chaque semaine ; Élite (Élite 2/Élite 1/Couronne) avec cut au classement du club. L'énergie et les blessures décident qui tu peux aligner.",
    tuto_cl_4_t:"Entraînement",
    tuto_cl_4_x:"Chaque joueur a son <b>plan</b> (un coup précis ou auto). Un bouton entraîne tout l'effectif d'un coup. Installations, salle de sport et salle vidéo améliorent le rendement.",
    tuto_cl_5_t:"Argent et recrues",
    tuto_cl_5_x:"Marché des agents libres (le recruteur déniche des perles), académie avec des espoirs, travaux du club, staff technique... et des <b>clubs rivaux</b> qui recrutent et viendront avec des offres pour les tiens : à toi de décider si tu vends.",
    tuto_cl_6_t:"L'objectif",
    tuto_cl_6_x:"Le <b>conseil</b> fixe un objectif de classement chaque saison : atteins-le et un budget extra arrive ; échoue deux ans de suite et <b>tu es limogé</b>. Gare au marché : les niveaux des autres sont des fourchettes — le recruteur affine ses rapports et flaire le plafond de chaque espoir.",
