    dil_beca_o2:"Danken und weitermachen",
    dil_beca_o2d:"Es wird eng, aber du bleibst frei.",
    dil_prensa_t:"Das Mikrofon nach der Niederlage",
    dil_prensa_x:"Ein Reporter wartet vor der Kabine. Er will hören, dass das Niveau der Tour am Boden ist. Du hast gerade verloren und kochst.",
