    dil_prensa_o2:"Zwei höfliche Sätze",
    dil_prensa_o2d:"Langweilig, aber niemand schneidet das Zitat mit.",
    dil_clinic_t:"Ein Vormittag mit den Kindern",
    dil_clinic_x:"Der Club, in dem du angefangen hast, bittet dich um ein Camp für seine Jugend. Sie zahlen nichts. Achtzig Kinder kommen, dazu die Eltern, alle mit dem Handy in der Hand.",
    dil_clinic_o1:"Hingehen und bis zum Schluss bleiben",
    dil_clinic_o1d:"Es ermüdet. Und es bleibt in Erinnerung.",
    dil_clinic_o1c:"Der Club schickt dir einen Umschlag, mit dem du nicht gerechnet hast.",
    dil_clinic_o2:"Diesmal nicht",
    dil_clinic_o2d:"Du ruhst dich aus. Jemand wird sich erinnern.",
    dil_dop_t:"Kontrolle um sieben Uhr morgens",
    dil_dop_x:"Zwei Dopingkontrolleure klingeln. Unangekündigt, rechtens und heute. In zwei Stunden war Training und die Nacht war kurz.",
